"""把 `ETenderDocument` 寫回 PCCES 匯得進去的電子標單 XML。

版面照 PCCES 4.3 匯出檔：UTF-8 帶 BOM、`standalone="no"` 宣告、CRLF 換行、兩格縮排、
空元素寫成 `<x />`、結尾不換行。文字裡的換行維持 LF（ArchEx001 的 InfoSummary CDATA 就是 LF），
解析器一律把換行讀成 LF，所以寫成 LF 才能逐位元組重現。

來源照實標：`applicationName` 一律寫本工具名、`signatureSealStamp` 一律寫空字串，
不仿造、不計算驗證碼。PCCES 匯入時會警告「非 PCCES 製作」，這是預期行為。

也因為標的不是 Pcces，PCCES 匯入時會把詳細表的 itemKey 依先序重編，寫出前先照那個規則編好、
公式引用一起換（`renumber.py`，PCX-002），所以 PCCES 匯出檔寫回來只有 itemKey 依先序排好的才逐位元組相同。
"""

from __future__ import annotations

import re
from datetime import date
from pathlib import Path

from .document import ETenderDocument, Item, ItemList, Node, ROOT_TAG
from .renumber import renumber_item_keys

APPLICATION_NAME = "PcxMcp"
# applicationVersion 是 PCCES 判斷 XML 格式版本的依據，不能寫本工具版本：
# 寫 0.3.0 會被當成 4.2 版格式匯入，表頭欄位整批掉、自辦工程被標成發包（2026-11-16 實測）。
# 所以保留來源檔的值，沒有來源值才寫這個目標格式版本。
FORMAT_VERSION = "4.3.1000.220"
# 根屬性只准改這四個；另外只有詳細表的 itemKey 與公式引用會重編，其餘節點的值與順序照模型寫回
PROVENANCE_ATTRS = ("createdDate", "applicationName", "applicationVersion", "signatureSealStamp")

XML_DECLARATION = '<?xml version="1.0" encoding="UTF-8" standalone="no"?>'
BOM = b"\xef\xbb\xbf"
NEWLINE = "\r\n"
INDENT = "  "

# XML 1.0 不允許的字元：寫進去 PCCES 與任何解析器都讀不回來
_INVALID_CHARS = re.compile("[\x00-\x08\x0b\x0c\x0e-\x1f￾￿]")


def provenance(created_date: date | None = None) -> dict[str, str]:
    return {
        "createdDate": (created_date or date.today()).isoformat(),
        "applicationName": APPLICATION_NAME,
        "applicationVersion": FORMAT_VERSION,
        "signatureSealStamp": "",
    }


def _stamp(attrs: dict[str, str], created_date: date | None) -> dict[str, str]:
    """原本有的屬性就地換值、保留順序；缺的接在命名空間宣告後面（PCCES 匯出檔的位置）。"""
    prov = provenance(created_date)
    if attrs.get("applicationVersion", "").strip():
        prov["applicationVersion"] = attrs["applicationVersion"]
    out = {k: prov.get(k, v) for k, v in attrs.items()}
    missing = [k for k in PROVENANCE_ATTRS if k not in out]
    if missing:
        keys = list(out)
        at = max((i + 1 for i, k in enumerate(keys) if k.startswith(("xmlns", "xsi:"))), default=0)
        keys[at:at] = missing
        out = {k: out.get(k, prov.get(k)) for k in keys}
    return out


def _check_chars(s: str, where: str) -> str:
    m = _INVALID_CHARS.search(s)
    if m:
        raise ValueError(f"{where} 含 XML 不允許的控制字元 U+{ord(m.group()):04X}，PCCES 讀不回來")
    return s


def _esc_text(s: str, where: str) -> str:
    s = _check_chars(s, where)
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\r", "&#13;")


def _esc_attr(s: str, where: str) -> str:
    s = _check_chars(s, where)
    s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
    # 屬性值裡的換行與 tab 不跳脫會被解析器正規化成空白
    return s.replace("\t", "&#9;").replace("\n", "&#10;").replace("\r", "&#13;")


def _item_node(it: Item) -> Node:
    return Node(it.tag, it.attrs, None, False, it.fields + [_item_node(c) for c in it.children])


def _list_node(lst: ItemList) -> Node:
    return Node(lst.tag, lst.attrs, None, False, [_item_node(i) for i in lst.items])


def _write(out: list[str], n: Node, level: int) -> None:
    pad = INDENT * level
    attrs = "".join(f' {k}="{_esc_attr(v, f"<{n.tag}> 的 {k}")}"' for k, v in n.attrs.items())
    if n.children:
        out.append(f"{pad}<{n.tag}{attrs}>")
        for c in n.children:
            _write(out, c, level + 1)
        out.append(f"{pad}</{n.tag}>")
    elif n.cdata:
        body = _check_chars(n.text or "", f"<{n.tag}>").replace("]]>", "]]]]><![CDATA[>")
        out.append(f"{pad}<{n.tag}{attrs}><![CDATA[{body}]]></{n.tag}>")
    elif n.text:
        out.append(f"{pad}<{n.tag}{attrs}>{_esc_text(n.text, f'<{n.tag}>')}</{n.tag}>")
    else:
        out.append(f"{pad}<{n.tag}{attrs} />")


def to_bytes(doc: ETenderDocument, *, created_date: date | None = None) -> bytes:
    """`created_date` 預設今天；測試給固定日期才比得了位元組。`doc` 不動，itemKey 重編只在寫出的內容裡。"""
    doc = renumber_item_keys(doc)
    children = [doc.tender_information, _list_node(doc.detail_list)]
    if doc.cost_breakdown_list is not None:
        children.append(_list_node(doc.cost_breakdown_list))
    if doc.resource_list is not None:
        children.append(_list_node(doc.resource_list))
    children += [doc.grand_total, *doc.extensions]
    root = Node(ROOT_TAG, _stamp(doc.root_attrs, created_date), None, False, children)
    lines = [XML_DECLARATION]
    _write(lines, root, 0)
    return BOM + NEWLINE.join(lines).encode("utf-8")


def write_document(doc: ETenderDocument, path: str | Path, *, created_date: date | None = None) -> Path:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(to_bytes(doc, created_date=created_date))
    return p
